    const mm = meshes.get(k);
    fillGeom(mm.solid, m.solid); fillGeom(mm.water, m.water);
    chunks.set(k, new Uint8Array(m.blocks));
    chunkReady.add(k);
    worker.postMessage({type: 'freeBlocks'});
    updateFogColor();
  } else if(m.type === 'remesh'){
    const k = m.cx + ',' + m.cz;
    if(!meshes.has(k)) buildChunkMeshes(k);
    const mm = meshes.get(k);
    fillGeom(mm.solid, m.solid); fillGeom(mm.water, m.water);
    if(!chunkReady.has(k)){ // 边缘区块没有 blocks 数据，请求一次
      requestChunk(m.cx, m.cz);
    }
  }
};

function buildChunkMeshes(k){
  const sg = new THREE.BufferGeometry();
  const wg = new THREE.BufferGeometry();
  const sm = new THREE.Mesh(sg, solidMat);
  const wm = new THREE.Mesh(wg, waterMat);
  wm.renderOrder = 2;
  sm.frustumCulled = true; wm.frustumCulled = true;
  scene.add(sm); scene.add(wm);
  meshes.set(k, {solid: sm, water: wm});
}
function fillGeom(mesh, g){
  const geo = mesh.geometry;
  if(!g){
    geo.setIndex([]); geo.setAttribute('position', new THREE.Float32BufferAttribute([], 3));
    return;
  }
  geo.setIndex(new THREE.BufferAttribute(g.idx, 1));
  geo.setAttribute('position', new THREE.BufferAttribute(g.pos, 3));
  geo.setAttribute('uv', new THREE.BufferAttribute(g.uv, 2));
  geo.setAttribute('col', new THREE.BufferAttribute(g.col, 1, true));
  geo.computeBoundingSphere();
  mesh.visible = true;
}

const chunks = new Map(); // "cx,cz" -> Uint8Array（来自 worker 的方块数据，用于物理/交互）
function requestChunk(cx, cz){
  const k = cx + ',' + cz;
  if(pending.has(k)) return;
  if(!meshes.has(k)) buildChunkMeshes(k);
  pending.add(k);
  worker.postMessage({type: 'chunk', cx, cz, edits: collectEdits(cx, cz)});
}
function collectEdits(cx, cz){
  const out = [];
  for(const [pk, id] of edits){
    const p = pk.split(',');
    const x = +p[0], y = +p[1], z = +p[2];
    if((x >> 4) === cx && (z >> 4) === cz) out.push([x, y, z, id]);
  }
  return out;
}
function blockAt(x, y, z){
  if(y < 0) return 11;
  if(y >= HEIGHT) return 0;
  const k = (x >> 4) + ',' + (z >> 4);
  const c = chunks.get(k);
  if(!c) return -1; // 未知
  return c[(((x & 15) << 4 | (z & 15)) << 7) | y];
}
function solidAt(x, y, z){
  const b = blockAt(Math.floor(x), Math.floor(y), Math.floor(z));
  if(b < 0) return true; // 未加载视为实心，防掉落
  const d = BLOCK_DEFS[b];
  return !!(b && d && !d.transparent && !d.cross);
}

function updateChunks(){
  const pcx = Math.floor(pos.x / 16), pcz = Math.floor(pos.z / 16);
  const need = [];
  for(let dx = -RENDER_DIST; dx <= RENDER_DIST; dx++)
    for(let dz = -RENDER_DIST; dz <= RENDER_DIST; dz++){
      if(dx * dx + dz * dz > (RENDER_DIST + 0.5) * (RENDER_DIST + 0.5)) continue;
      need.push([(pcx + dx) * 100 + (pcz + dz), pcx + dx, pcz + dz]);
    }
  need.sort((a, b) => {
    const da = (a[1] - pcx) * (a[1] - pcx) + (a[2] - pcz) * (a[2] - pcz);
    const db = (b[1] - pcx) * (b[1] - pcx) + (b[2] - pcz) * (b[2] - pcz);
    return da - db;
  });
  for(const [k, cx, cz] of need) requestChunk(cx, cz);
  // 卸载远处区块
  for(const k of [...meshes.keys()]){
    const [cx, cz] = k.split(',').map(Number);
    const dx = cx - pcx, dz = cz - pcz;
    if(dx * dx + dz * dz > (RENDER_DIST + 2) * (RENDER_DIST + 2)){
      const mm = meshes.get(k);
      scene.remove(mm.solid); scene.remove(mm.water);
      mm.solid.geometry.dispose(); mm.water.geometry.dispose();
      meshes.delete(k); chunks.delete(k); chunkReady.delete(k);
    }
  }
}

