      const x = Math.floor(pos.x + Math.cos(a) * r), z = Math.floor(pos.z + Math.sin(a) * r);
      for(let y = HEIGHT - 2; y > 4; y--){
        const b = blockAt(x, y, z);
        if(b > 0 && b !== 7 && b !== 6 && b !== 14 && !BLOCK_DEFS[b].cross){ best = [x, y, z]; break; }
        if(b === -1) break;
      }
