const invCounts = new Array(27).fill(0);
function giveItem(id){
  for(let i = 0; i < 9; i++) if(hotbar[i] === id && hotbarCounts[i] < 64){ hotbarCounts[i]++; updateHotbar(); return; }
  for(let i = 0; i < 9; i++) if(!hotbar[i]){ hotbar[i] = id; hotbarCounts[i] = 1; updateHotbar(); return; }
  for(let i = 0; i < 27; i++) if(invSlots[i] === id && invCounts[i] < 64){ invCounts[i]++; renderInv(); return; }
  for(let i = 0; i < 27; i++) if(!invSlots[i]){ invSlots[i] = id; invCounts[i] = 1; renderInv(); return; }
