  const dayCol = new THREE.Color(0xc3ddff), nightCol = new THREE.Color(0x0b0e1a);
  const duskCol = new THREE.Color(0xe8935a);
  const skyT = new THREE.Color().copy(nightCol).lerp(dayCol, dayF);
  const duskAmt = Math.max(0, 1 - Math.abs(sunH) / 0.3) * (dayF > 0 ? 1 : 0.4);
  skyT.lerp(duskCol, duskAmt * 0.45);

  // 水下效果
  const camBlock = blockAt(Math.floor(camera.position.x), Math.floor(camera.position.y), Math.floor(camera.position.z));
  const underWater = camBlock === 7;
  if(underWater){ skyT.setRGB(0.08, 0.22, 0.45); }

  scene.fog.color.copy(skyT);
  scene.fog.near = underWater ? 2 : RENDER_DIST * 16 * 0.55;
  scene.fog.far = underWater ? 22 : RENDER_DIST * 16 * 0.98;
  skyMat.uniforms.top.value.copy(skyT).multiplyScalar(1.06);
  skyMat.uniforms.bot.value.copy(skyT);
  solidMat.uniforms.fogNear.value = scene.fog.near;
  solidMat.uniforms.fogFar.value = scene.fog.far;
  waterMat.uniforms.fogNear.value = scene.fog.near;
  waterMat.uniforms.fogFar.value = scene.fog.far;
  solidMat.uniforms.fogColor.value.copy(skyT);
  waterMat.uniforms.fogColor.value.copy(skyT);
  renderer.setClearColor(skyT);
  solidMat.uniforms.dayF.value = 0.14 + 0.86 * dayF;
  waterMat.uniforms.dayF.value = solidMat.uniforms.dayF.value;
