    if(lx < LB - 1 && skyL[i + (LB << 7)] < s - 1) { q.push(i); continue; }
    if(lz > 0      && skyL[i - (1 << 7)] < s - 1)  { q.push(i); continue; }
    if(lz < LB - 1 && skyL[i + (1 << 7)] < s - 1)  { q.push(i); continue; }
    if(y > 0       && skyL[i - 1] < s - 1)         { q.push(i); continue; }
