      else if(d === 3) nz++; else if(d === 4) ny--; else ny++;
      if(nx < 0 || nx >= LB || nz < 0 || nz >= LB || ny < 0 || ny >= HEIGHT) continue;
      const nb = getW(ox + nx, ny, oz + nz);
      if(opaqueAt(nb)) continue;
