    for(let lz = 0; lz < RL; lz++){
      const base = rIdx(lx, lz, 0);
      const top = regTop[lx * RL + lz];
      for(let y = 0; y <= top; y++){
        const i = base | y;
        const s = regSky[i];
        if(s < 2) continue;
        if((lx > 0      && regSky[i - (RL << 7)] < s - 1) ||
