    for(let fi = 0; fi < 6; fi++){
      const f = FACES[fi];
      const nx = wx + f.d[0], ny = y + f.d[1], nz = wz + f.d[2];
      const n = getW(nx, ny, nz);
      // 可见面判定
      if(isWater){ if(n === 7 || opaqueAt(n)) continue; }
      else if(b === 13){ if(n === 13 || opaqueAt(n)) continue; }
      else if(opaqueAt(n)) continue;
      if(isWater && fi === 3 && above === 7) continue;

      const tile = faceTile(def.tex, fi);
      const [u0, v0, u1, v1] = TUV(tile);
      lightAt(nx, ny, nz, tmpL);
      const s = tmpL[0] / 15, bl = tmpL[1] / 15;

      const verts = [];
      for(const c of f.c){
        let vy = y + c[1];
        if(topOffset && c[1] === 1) vy = y + 1 - topOffset;
        // 环境光遮蔽
        let m = f.m;
        if(!isWater){
          let sa, sb, ax, az, bx, bz; // 两个切向轴
          if(f.d[0] !== 0){ ax=0; az=1; bx=0; bz=2; sa=c[1]?1:-1; sb=c[2]?1:-1; }
          else if(f.d[1] !== 0){ ax=0; az=0; bx=2; bz=0; sa=c[0]?1:-1; sb=c[2]?1:-1; }
          else { ax=0; az=0; bx=1; bz=0; sa=c[0]?1:-1; sb=c[1]?1:-1; }
          const P = (dx, dy, dz) => opaqueAt(getW(nx+dx, ny+dy, nz+dz)) ? 1 : 0;
          const o1 = f.d[0]!==0 ? [0, sa, 0] : f.d[1]!==0 ? [sa, 0, 0] : [sa, 0, 0];
          const o2 = f.d[0]!==0 ? [0, 0, sb] : f.d[1]!==0 ? [0, 0, sb] : [0, sb, 0];
          const s1 = P(o1[0], o1[1], o1[2]);
          const s2 = P(o2[0], o2[1], o2[2]);
          const sc = P(o1[0]+o2[0], o1[1]+o2[1], o1[2]+o2[2]);
          const ao = (s1 && s2) ? 0 : 3 - (s1 + s2 + sc);
          m = f.m * aoMult[ao];
        }
        verts.push([lx + c[0], vy, lz + c[2], u0 + (u1 - u0) * c[3], v0 + (v1 - v0) * c[4]]);
      }
      pushQuad(isWater ? W : S, verts, s, bl, verts === null ? 1 : m);
    }
  }
  const pack = A => A.pos.length === 0 ? null : {
    pos: new Float32Array(A.pos), uv: new Float32Array(A.uv),
    col: new Uint8Array(A.col), idx: new Uint32Array(A.idx)
  };
  return {solid: pack(S), water: pack(W)};
}

/* ---------------- 消息处理 ---------------- */
function mergeEdits(edits){
  if(!edits) return;
  for(const e of edits){
    const x = e[0], y = e[1], z = e[2], id = e[3];
    const k = key(x >> 4, z >> 4);
    let em = editMap.get(k);
    if(!em){ em = new Map(); editMap.set(k, em); }
    em.set(idx(x & 15, z & 15, y), id);
    const pk = x + ',' + y + ',' + z;
    if(id === 31 || id === 10) torchSet.add(pk);
    else torchSet.delete(pk);
    const c = cache.get(k);
    if(c) c[idx(x & 15, z & 15, y)] = id;
  }
}
function postGeometry(type, cx, cz, withBlocks){
  const res = buildMesh(cx, cz);
  const msg = {type, cx, cz, solid: res.solid, water: res.water};
  const tr = [];
  if(withBlocks){
    msg.blocks = ensureCol(cx, cz).slice(0);
    tr.push(msg.blocks.buffer);
  }
  for(const g of [res.solid, res.water]) if(g){
    tr.push(g.pos.buffer, g.uv.buffer, g.col.buffer, g.idx.buffer);
  }
  postMessage(msg, tr);
}
function handleEdit(x, y, z, id){
  mergeEdits([[x, y, z, id]]);
  const cx = x >> 4, cz = z >> 4;
  const cands = new Set();
  for(let dx = -1; dx <= 1; dx++) for(let dz = -1; dz <= 1; dz++){
    const ncx = ((x - 14) >> 4) + dx, ncz = ((z - 14) >> 4) + dz;
    if(ncx >= (x - 14) >> 4 && ncx <= (x + 14) >> 4 && ncz >= (z - 14) >> 4 && ncz <= (z + 14) >> 4)
      cands.add(ncx + ',' + ncz);
  }
  cands.add(cx + ',' + cz);
  for(const k of cands){
    const [ccx, ccz] = k.split(',').map(Number);
    computeLight(ccx, ccz);
    const ns = extractCol(ccx, ccz, skyL), nb = extractCol(ccx, ccz, blkL);
    const prev = lightCache.get(k);
    let changed = !prev || prev.sky.length !== ns.length;
    if(!changed){
      for(let i = 0; i < ns.length; i++) if(prev.sky[i] !== ns[i] || prev.blk[i] !== nb[i]){ changed = true; break; }
    }
    const borderN = (ccx === cx && ccz === cz + 1 && (z & 15) === 15) ||
                    (ccx === cx && ccz === cz - 1 && (z & 15) === 0) ||
                    (ccz === cz && ccx === cx + 1 && (x & 15) === 15) ||
                    (ccz === cz && ccx === cx - 1 && (x & 15) === 0);
    if(changed || borderN || (ccx === cx && ccz === cz)){
      lightCache.set(k, {sky: ns, blk: nb});
      postGeometry('remesh', ccx, ccz, false);
    }
  }
}

self.onmessage = e => {
  const m = e.data;
  if(m.type === 'init'){
    seed = m.seed | 0;
    cache.clear(); editMap.clear(); lightCache.clear(); torchSet = new Set();
    Lcx = 1e9; Lcz = 1e9;
  }
  else if(m.type === 'chunk'){
    mergeEdits(m.edits);
    ensureCol(m.cx, m.cz);
    postGeometry('chunk', m.cx, m.cz, true);
  }
  else if(m.type === 'edit'){
    handleEdit(m.x, m.y, m.z, m.id);
  }
};
