{"content":"'use strict';
/* ============================================================
   Minecraft 网页版 — 主程序（渲染 / 物理 / 交互 / UI / 音效 / 存档）
   ============================================================ */
if(!window.Worker){ document.getElementById('load').innerHTML = '浏览器不支持 Web Worker'; throw new Error('no worker'); }

const HEIGHT = 128, SEA = 32;
const RENDER_DIST = 6;           // 渲染距离（区块）
const DAY_LEN = 300;             // 一天的秒数
const GRAVITY = 30, JUMP_V = 8.8;
const EYE = 1.62, PR = 0.3, PH = 1.8;

const BLOCK_NAMES = ['','草方块','泥土','石头','沙子','橡木原木','橡树树叶','水','橡木木板','圆石','萤石','基岩',
  '雪块','玻璃','虞美人','蒲公英','沙砾','煤矿石','铁矿石','金矿石','钻石矿石','雪层','火把'];
const BLOCK_NAMES_EN = ['','Grass Block','Dirt','Stone','Sand','Oak Log','Oak Leaves','Water','Oak Planks','Cobblestone','Glowstone','Bedrock',
  'Snow Block','Glass','Poppy','Dandelion','Gravel','Coal Ore','Iron Ore','Gold Ore','Diamond Ore','Snow','Torch'];
const ORE_DROPS = {17:9, 18:9, 19:9, 20:9};
const CREATIVE = new URLSearchParams(location.search).has('creative');

/* ---------------- 音效（WebAudio 程序化） ---------------- */
let AC = null;
function ac(){ if(!AC){ try{ AC = new (window.AudioContext||window.webkitAudioContext)(); }catch(e){} } return AC; }
function noiseBuf(dur){
  const a = ac(); if(!a) return null;
  const n = Math.floor(a.sampleRate * dur);
  const b = a.createBuffer(1, n, a.sampleRate);
  const d = b.getChannelData(0);
  for(let i = 0; i < n; i++) d[i] = Math.random() * 2 - 1;
  return b;
}
let _stepBuf = null;
function sfx(kind, blockId){
  const a = ac(); if(!a) return;
  if(a.state === 'suspended') a.resume();
  const t = a.currentTime;
  const g = a.createGain(); g.connect(a.destination);
  const b = blockId || 3;
  if(kind === 'dig'){
    const src = a.createBufferSource(); src.buffer = noiseBuf(0.16);
    const f = a.createBiquadFilter();
    if(b === 3 || b === 9 || b === 10 || (b >= 17 && b <= 20)){ f.type = 'lowpass'; f.frequency.value = 900; }
    else if(b === 4 || b === 16){ f.type = 'bandpass'; f.frequency.value = 2600; }
    else { f.type = 'lowpass'; f.frequency.value = 1600; }
    src.connect(f); f.connect(g);
    g.gain.setValueAtTime(0.25, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.16);
    src.start(t); src.stop(t + 0.17);
  } else if(kind === 'place'){
    const src = a.createBufferSource(); src.buffer = noiseBuf(0.09);
    const f = a.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 1100;
    src.connect(f); f.connect(g);
    g.gain.setValueAtTime(0.3, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.09);
    src.start(t); src.stop(t + 0.1);
  } else if(kind === 'step'){
    if(!_stepBuf) _stepBuf = noiseBuf(0.08);
    const src = a.createBufferSource(); src.buffer = _stepBuf;
    const f = a.createBiquadFilter(); f.type = 'lowpass';
    f.frequency.value = 500 + Math.random() * 700;
    src.connect(f); f.connect(g);
    g.gain.setValueAtTime(0.12, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.08);
    src.start(t); src.stop(t + 0.09);
  } else if(kind === 'pop'){
    const o = a.createOscillator(); o.type = 'sine';
    o.frequency.setValueAtTime(660, t); o.frequency.exponentialRampToValueAtTime(190, t + 0.12);
    o.connect(g); g.gain.setValueAtTime(0.2, t); g.gain.exponentialRampToValueAtTime(0.001, t + 0.13);
    o.start(t); o.stop(t + 0.14);
  }
}

/* ---------------- 纹理集（Canvas 16x16 程序化生成） ---------------- */
const T = 16, TS = T;
const atlasC = document.createElement('canvas');
atlasC.width = TS * 8; atlasC.height = TS * 3;
const actx = atlasC.getContext('2d');
function px(ti, x, y, c){
  const col = ti % 8, row = (ti / 8) | 0;
  actx.fillStyle = c;
  actx.fillRect(col * TS + x, row * TS + y, 1, 1);
}
function fill(ti, c){ for(let y = 0; y < T; y++) for(let x = 0; x < T; x++) px(ti, x, y, c); }
function speck(ti, cols, n){
  for(let i = 0; i < n; i++){
    const x = (Math.random() * T) | 0, y = (Math.random() * T) | 0;
    px(ti, x, y, cols[(Math.random() * cols.length) | 0]);
  }
}
function shade(ti, fn){ for(let y = 0; y < T; y++) for(let x = 0; x < T; x++){ const c = fn(x, y); if(c) px(ti, x, y, c); } }

// 0 草顶
fill(0, '#7cbd6b'); speck(0, ['#6aa85a','#8ccb7a','#5f9e51'], 90);
// 1 草侧
fill(1, '#8a6244'); speck(1, ['#7a5539','#966d4d'], 40);
for(let x = 0; x < T; x++){ const d = 2 + ((x * 7 + 3) % 3); for(let y = 0; y < d; y++) px(1, x, y, y === d - 1 ? '#6aa85a' : '#7cbd6b'); }
// 2 土
fill(2, '#8a6244'); speck(2, ['#75533a','#966d4d','#6d4d34'], 70);
// 3 石
fill(3, '#8d8d8d'); speck(3, ['#7d7d7d','#9a9a9a','#858585'], 80);
// 4 沙
