// 5 原木侧
fill(5, '#6b5334'); for(let x = 0; x < T; x++){ const c = (x % 4 < 2) ? '#5d4728' : '#75603e'; for(let y = 0; y < T; y++) if(Math.random() < 0.85) px(5, x, y, c); }
// 6 原木顶
fill(6, '#b8945f'); shade(6, (x, y) => { const r = Math.max(Math.abs(x - 7.5), Math.abs(y - 7.5)); return r > 6.5 ? '#6b5334' : (r > 4.5 ? '#a3814f' : ((x + y) % 3 ? '#c4a06a' : '#b8945f')); });
// 7 叶
fill(7, '#3e7a2e'); speck(7, ['#356b27','#4a8c37','#2c5c1f','#57a044'], 130);
for(let i = 0; i < 14; i++){ const x = (Math.random() * T) | 0, y = (Math.random() * T) | 0; actx.clearRect((7 / 8) * 0 + ((7 % 8) * TS + x), (((7 / 8) | 0) * TS + y), 1, 1); }
// 8 水
fill(8, '#3f76e4'); speck(8, ['#3a6fd8','#4580ea','#3568cc'], 50);
// 9 木板
fill(9, '#b8945f'); for(let y = 0; y < T; y++){ if(y % 4 === 3) for(let x = 0; x < T; x++) px(9, x, y, '#8a6d42'); else speck(9, [], 0); }
speck(9, ['#ad8955','#c49e69'], 40);
for(let y = 0; y < T; y += 4){ px(9, (y * 5 + 3) % T, y, '#8a6d42'); px(9, (y * 5 + 4) % T, y + 1, '#8a6d42'); }
// 10 圆石
fill(10, '#828282'); shade(10, (x, y) => { const cx2 = (x % 8) - 4, cy2 = (y % 8) - 4; const d = Math.sqrt(cx2 * cx2 + cy2 * cy2); return d < 2.6 ? '#9c9c9c' : (d < 3.4 ? '#6e6e6e' : null); });
speck(10, ['#8a8a8a','#767676'], 50);
// 11 基岩
fill(11, '#565656'); speck(11, ['#333','#777','#444','#666'], 150);
// 12 雪顶
fill(12, '#f4fbfb'); speck(12, ['#e8f2f2','#ffffff'], 30);
// 13 雪侧
fill(13, '#8a6244'); for(let x = 0; x < T; x++){ const d = 3 + ((x * 5 + 2) % 3); for(let y = 0; y < d; y++) px(13, x, y, y === d - 1 ? '#e8f2f2' : '#f4fbfb'); }
speck(13, ['#75533a'], 20);
// 14 玻璃（透明）
actx.clearRect(14 % 8 * TS, 0, TS, TS);
for(let i = 0; i < T; i++){ px(14, i, 0, '#dff3f3'); px(14, i, T - 1, '#dff3f3'); px(14, 0, i, '#dff3f3'); px(14, T - 1, i, '#dff3f3'); }
for(let i = 2; i < 7; i++) px(14, i, 9 - i + 2, 'rgba(255,255,255,0.55)');
// 15 红花
actx.clearRect(15 % 8 * TS, TS, TS, TS);
px(15, 7, 15, '#3d7a2a'); px(15, 8, 14, '#3d7a2a'); px(15, 8, 13, '#3d7a2a'); px(15, 7, 12, '#3d7a2a');
px(15, 6, 11, '#3d7a2a'); px(15, 8, 11, '#3d7a2a'); px(15, 7, 10, '#3d7a2a');
for(const [dx, dy] of [[7,7],[6,6],[8,6],[7,5],[6,8],[8,8],[5,7],[9,7]]) px(15, dx, dy, '#d0342c');
px(15, 7, 6, '#7a1f1a'); px(15, 8, 7, '#e04a3a');
// 16 黄花
actx.clearRect(0, 2 * TS, TS, TS);
px(16, 7, 15, '#3d7a2a'); px(16, 8, 14, '#3d7a2a'); px(16, 7, 13, '#3d7a2a'); px(16, 8, 12, '#3d7a2a'); px(16, 7, 11, '#3d7a2a');
for(const [dx, dy] of [[7,7],[6,6],[8,6],[7,5],[6,8],[8,8],[5,7],[9,7],[7,9],[5,5],[9,5]]) px(16, dx, dy, '#f0c818');
px(16, 7, 7, '#c79a0e');
// 17 沙砾
fill(17, '#7f7b78'); speck(17, ['#8d8884','#6e6a67','#9a938e','#5f5b58'], 110);
// 18 煤
fill(18, '#8d8d8d'); for(const [dx, dy] of [[3,4],[4,4],[3,5],[10,3],[11,3],[11,4],[6,10],[7,10],[7,11],[12,11],[5,7]]){ px(18, dx, dy, '#2c2c2c'); px(18, dx, dy + 1, '#1f1f1f'); }
// 19 铁
fill(19, '#8d8d8d'); for(const [dx, dy] of [[3,4],[4,4],[10,3],[11,4],[6,10],[7,11],[12,11],[5,7]]){ px(19, dx, dy, '#e8c9a8'); px(19, dx + 1, dy, '#d8b890'); }
// 20 金
fill(20, '#8d8d8d'); for(const [dx, dy] of [[3,4],[4,5],[10,3],[11,4],[6,10],[12,11],[5,7]]){ px(20, dx, dy, '#f5d93d'); px(20, dx + 1, dy, '#e0be28'); }
// 21 钻
fill(21, '#8d8d8d'); for(const [dx, dy] of [[3,4],[4,4],[10,3],[11,4],[6,10],[7,10],[12,11],[5,7]]){ px(21, dx, dy, '#4aedd9'); px(21, dx + 1, dy + 1, '#2fc9b5'); }
// 22 萤石
fill(22, '#d4a852'); speck(22, ['#e8c46a','#c4923c','#f5e08a'], 90); speck(22, ['#fff3b8'], 25);
// 23 火把（杆+头，中间竖条）
actx.clearRect(23 % 8 * TS, 2 * TS, TS, TS);
for(let y = 4; y < 15; y++) for(let x = 7; x <= 8; x++) px(23, x, y, '#6b5334');
for(let y = 3; y <= 4; y++) for(let x = 7; x <= 8; x++) px(23, x, y, '#ffd83d');
px(23, 7, 2, '#fff1a8'); px(23, 8, 2, '#ffb52e');

const atlasTex = new THREE.CanvasTexture(atlasC);
atlasTex.magFilter = THREE.NearestFilter;
atlasTex.minFilter = THREE.NearestFilter;
atlasTex.generateMipmaps = false;

/* ---------------- 图标（用于 UI） ---------------- */
function iconCanvas(tile){
  const c = document.createElement('canvas'); c.width = 32; c.height = 32;
  const cx2 = c.getContext('2d'); cx2.imageSmoothingEnabled = false;
  const col = tile % 8, row = (tile / 8) | 0;
  cx2.drawImage(atlasC, col * TS, row * TS, TS, TS, 0, 0, 32, 32);
  return c.toDataURL();
}

/* ---------------- Three.js 场景 ---------------- */
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, innerWidth / innerHeight, 0.08, 620);
const renderer = new THREE.WebGLRenderer({antialias: false, canvas: document.getElementById('game')});
renderer.setSize(innerWidth, innerHeight);
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.6));

// 天空
const skyGeo = new THREE.SphereGeometry(560, 24, 16);
const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide, depthWrite: false,
  uniforms: {top: {value: new THREE.Color(0x79a6ff)}, bot: {value: new THREE.Color(0xc3ddff)}},
  vertexShader: 'varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }',
  fragmentShader: 'uniform vec3 top; uniform vec3 bot; varying vec3 vP; void main(){ float h = normalize(vP).y; gl_FragColor = vec4(mix(bot, top, clamp(h*1.4+0.25,0.0,1.0)), 1.0); }'
});
const skyMesh = new THREE.Mesh(skyGeo, skyMat);
scene.add(skyMesh);

// 太阳 / 月亮
const sunMesh = new THREE.Mesh(new THREE.PlaneGeometry(46, 46), new THREE.MeshBasicMaterial({color: 0xffffcc, fog: false, depthWrite: false}));
const moonMesh = new THREE.Mesh(new THREE.PlaneGeometry(30, 30), new THREE.MeshBasicMaterial({color: 0xdfe6ee, fog: false, depthWrite: false, transparent: true}));
scene.add(sunMesh); scene.add(moonMesh);
const sunLight = new THREE.DirectionalLight(0xffffff, 1.0);
scene.add(sunLight); scene.add(sunLight.target);
const ambLight = new THREE.AmbientLight(0xffffff, 1.0);
scene.add(ambLight);

scene.fog = new THREE.Fog(0xc3ddff, RENDER_DIST * 16 * 0.55, RENDER_DIST * 16 * 0.98);

// 星星
const starGeo = new THREE.BufferGeometry();
{
  const sp = [];
  for(let i = 0; i < 350; i++){
    const t = Math.random() * Math.PI * 2, p = Math.acos(Math.random() * 2 - 1);
    const r = 520;
    sp.push(r * Math.sin(p) * Math.cos(t), Math.abs(r * Math.cos(p)), r * Math.sin(p) * Math.sin(t));
  }
  starGeo.setAttribute('position', new THREE.Float32BufferAttribute(sp, 3));
}
const starMat = new THREE.PointsMaterial({color: 0xffffff, size: 1.6, sizeAttenuation: false, transparent: true, opacity: 0, fog: false, depthWrite: false});
const stars = new THREE.Points(starGeo, starMat);
scene.add(stars);

// 材质
function makeMat(transparent){
  return new THREE.ShaderMaterial({
    transparent, depthWrite: !transparent,
    vertexColors: true, side: transparent ? THREE.DoubleSide : THREE.FrontSide,
    uniforms: {
      map: {value: atlasTex},
      sunDir: {value: new THREE.Vector3(0.5, 1, 0.2)},
      dayF: {value: 1},
      fogColor: {value: new THREE.Color(0xc3ddff)},
      fogNear: {value: scene.fog.near}, fogFar: {value: scene.fog.far}
    },
    vertexShader: `
      attribute vec3 col;
      varying vec2 vUv; varying vec3 vCol; varying float vDist;
      void main(){
        vUv = uv; vCol = col;
        vec4 mv = modelViewMatrix * vec4(position, 1.0);
        vDist = -mv.z;
        gl_Position = projectionMatrix * mv;
      }`,
    fragmentShader: `
      uniform sampler2D map; uniform vec3 sunDir; uniform float dayF;
      uniform vec3 fogColor; uniform float fogNear; uniform float fogFar;
      varying vec2 vUv; varying vec3 vCol; varying float vDist;
      void main(){
        vec4 tex = texture2D(map, vUv);
        if(tex.a < 0.15) discard;
        float sky = vCol.r / 15.0;
        float blk = vCol.g / 15.0;
        float mult = vCol.b;
        float day = dayF;
        float light = min(1.0, sky * (0.06 + 0.94 * day) + blk * 0.96);
        light = 0.04 + 0.96 * light;
        vec3 c = tex.rgb * light * mult;
        float f = smoothstep(fogNear, fogFar, vDist);
        c = mix(c, fogColor, f);
        gl_FragColor = vec4(c, tex.a);
      }`
  });
}
const solidMat = makeMat(false);
const waterMat = makeMat(true);

// 选框
const selBox = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(1.002, 1.002, 1.002)),
  new THREE.LineBasicMaterial({color: 0x000000, transparent: true, opacity: 0.6})
);
selBox.visible = false;
scene.add(selBox);

// 手持方块
let handMesh = null;
function buildHandMesh(id){
  if(handMesh){ scene.remove(handMesh); handMesh = null; }
  if(!id) return;
  const def = BLOCK_DEFS[id];
  const geo = new THREE.BoxGeometry(0.3, 0.3, 0.3);
  // 用小 canvas 给方块各面上色纹理
  const mats = [];
  const tiles = [def.tex.side !== undefined ? def.tex.side : def.tex.all, def.tex.side !== undefined ? def.tex.side : def.tex.all,
                 def.tex.top !== undefined ? def.tex.top : def.tex.all, def.tex.bottom !== undefined ? def.tex.bottom : def.tex.all,
                 def.tex.side !== undefined ? def.tex.side : def.tex.all, def.tex.side !== undefined ? def.tex.side : def.tex.all];
  for(const ti of tiles){
    const c = document.createElement('canvas'); c.width = 16; c.height = 16;
    const cc = c.getContext('2d');
    cc.drawImage(atlasC, (ti % 8) * TS, ((ti / 8) | 0) * TS, TS, TS, 0, 0, 16, 16);
    const t = new THREE.CanvasTexture(c);
    t.magFilter = THREE.NearestFilter; t.minFilter = THREE.NearestFilter;
    mats.push(new THREE.MeshLambertMaterial({map: t, transparent: id === 7 || id === 13}));
  }
  handMesh = new THREE.Mesh(geo, mats);
  handMesh.renderOrder = 999;
  scene.add(handMesh);
}
function setHandTransform(){
  if(!handMesh) return;
  const bob = Math.sin(walkCycle) * 0.02;
  handMesh.position.set(0.42 + bob, -0.42 + Math.abs(bob) * 0.6, -0.7);
  handMesh.rotation.set(0.2, Math.PI / 5, 0.1);
  handMesh.visible = !document.pointerLockElement;
}
