/* ---------------- 射线拾取（DDA） ---------------- */
function raycast(maxDist){
  const dir = new THREE.Vector3(0, 0, -1).applyEuler(camera.rotation ? camera.rotation : new THREE.Euler());
  // 直接用 yaw/pitch 计算
  const cp = Math.cos(yawPitch.pitch), sp = Math.sin(yawPitch.pitch);
  const cy = Math.cos(yawPitch.yaw), sy = Math.sin(yawPitch.yaw);
  dir.set(-sy * cp, sp, -cy * cp).normalize();
  const o = new THREE.Vector3(pos.x, pos.y + EYE, pos.z);
  let x = Math.floor(o.x), y = Math.floor(o.y), z = Math.floor(o.z);
  const stepX = dir.x > 0 ? 1 : -1, stepY = dir.y > 0 ? 1 : -1, stepZ = dir.z > 0 ? 1 : -1;
  const tdx = Math.abs(1 / (dir.x || 1e-9)), tdy = Math.abs(1 / (dir.y || 1e-9)), tdz = Math.abs(1 / (dir.z || 1e-9));
  let tmx = (dir.x > 0 ? (x + 1 - o.x) : (o.x - x)) * tdx;
  let tmy = (dir.y > 0 ? (y + 1 - o.y) : (o.y - y)) * tdy;
  let tmz = (dir.z > 0 ? (z + 1 - o.z) : (o.z - z)) * tdz;
  let face = [0, 0, 0], t = 0;
  for(let i = 0; i < 220; i++){
    const b = blockAt(x, y, z);
    if(b > 0 && b !== 7){ return {x, y, z, b, face}; }
    if(b === 7 && false) return {x, y, z, b, face};
    if(tmx < tmy && tmx < tmz){ x += stepX; t = tmx; tmx += tdx; face = [-stepX, 0, 0]; }
    else if(tmy < tmz){ y += stepY; t = tmy; tmy += tdy; face = [0, -stepY, 0]; }
    else { z += stepZ; t = tmz; tmz += tdz; face = [0, 0, -stepZ]; }
    if(t > maxDist) break;
  }
  return null;
}

/* ---------------- 破坏 / 放置 ---------------- */
let breakTarget = null, breakProgress = 0, breakTotal = 1;
function startBreak(){
  const hit = raycast(5);
  if(!hit) return;
  if(hit.b === 11){ toast('基岩无法破坏'); return; }
  breakTarget = hit;
  breakTotal = hardness(hit.b);
  breakProgress = 0;
}
function hardness(b){
  const H = {1:0.9, 2:0.75, 3:2.2, 4:0.75, 5:2.0, 6:0.3, 8:2.0, 9:2.0, 10:0.4, 12:0.3, 13:0.4, 14:0.05, 15:0.05, 16:0.9, 17:3.0, 18:3.0, 19:3.0, 20:3.0, 21:0.5, 22:0.05};
  return H[b] || 1;
}
function finishBreak(hit){
  const id = hit.b;
  sendEdit(hit.x, hit.y, hit.z, 0);
  sfx('dig', id); sfx('pop');
  const drop = ORE_DROPS[id] || id;
  if(!CREATIVE) giveItem(drop);
  spawnParticles(hit.x + 0.5, hit.y + 0.5, hit.z + 0.5, id);
  breakTarget = null;
}
function placeBlock(){
  const hit = raycast(5);
  if(!hit) return;
  const id = hotbar[selSlot];
  if(!id) return;
  const px2 = hit.x + hit.face[0], py2 = hit.y + hit.face[1], pz2 = hit.z + hit.face[2];
  if(py2 < 1 || py2 >= HEIGHT) return;
  const tb = blockAt(px2, py2, pz2);
  if(tb !== 0 && tb !== 7) return;
  // 与玩家碰撞检测
  const d = BLOCK_DEFS[id];
  if(!d.cross && id !== 7){
    const e = 0.001;
    if(pos.x + PR > px2 - e && pos.x - PR < px2 + 1 + e &&
       pos.z + PR > pz2 - e && pos.z - PR < pz2 + 1 + e &&
       pos.y + PH > py2 - e && pos.y < py2 + 1 + e){
      return;
    }
  }
  if(d.cross && !solidAt(px2, py2 - 1, pz2)) return; // 花草需要地面
  sendEdit(px2, py2, pz2, id);
  sfx('place', id);
  if(!CREATIVE && hotbar[selSlot] !== undefined){
    hotbarCounts[selSlot]--;
    if(hotbarCounts[selSlot] <= 0){ hotbar[selSlot] = 0; hotbarCounts[selSlot] = 0; }
    updateHotbar();
  }
  swing();
}
function pickBlock(){
  const hit = raycast(5);
  if(!hit) return;
  const id = ORE_DROPS[hit.b] || hit.b;
  const idx2 = hotbar.indexOf(id);
  if(idx2 >= 0){ selSlot = idx2; }
  else { hotbar[selSlot] = id; hotbarCounts[selSlot] = CREATIVE ? Infinity : (hotbarCounts[selSlot] || 64); }
  updateHotbar();
}
function sendEdit(x, y, z, id){
  const pk = x + ',' + y + ',' + z;
  edits.set(pk, id);
  worker.postMessage({type: 'edit', x, y, z, id});
  const c = chunks.get((x >> 4) + ',' + (z >> 4));
  if(c) c[(((x & 15) << 4 | (z & 15)) << 7) | y] = id;
  markDirtySave();
}
