const partGeo = new THREE.BoxGeometry(0.12, 0.12, 0.12);
const particles = [];
function spawnParticles(x, y, z, blockId){
  const def = BLOCK_DEFS[blockId];
  const tile = def.tex.all !== undefined ? def.tex.all : (def.tex.side ?? def.tex.top ?? 3);
  const c = document.createElement('canvas'); c.width = 4; c.height = 4;
  const cc = c.getContext('2d');
  cc.drawImage(atlasC, (tile % 8) * TS + 6, ((tile / 8) | 0) * TS + 6, 4, 4, 0, 0, 4, 4);
  const data = cc.getImageData(0, 0, 4, 4).data;
  for(let i = 0; i < 10; i++){
    const mat = new THREE.MeshBasicMaterial({color: new THREE.Color(data[(i % 16) * 4] / 255, data[(i % 16) * 4 + 1] / 255, data[(i % 16) * 4 + 2] / 255)});
    const m = new THREE.Mesh(partGeo, mat);
    m.position.set(x + (Math.random() - 0.5) * 0.6, y + (Math.random() - 0.5) * 0.6, z + (Math.random() - 0.5) * 0.6);
    scene.add(m);
    particles.push({m, vx: (Math.random() - 0.5) * 3, vy: Math.random() * 3.5 + 1, vz: (Math.random() - 0.5) * 3, life: 0.6 + Math.random() * 0.3});
  }
}
function updateParticles(dt){
  for(let i = particles.length - 1; i >= 0; i--){
    const p = particles[i];
    p.life -= dt;
    if(p.life <= 0){ scene.remove(p.m); particles.splice(i, 1); continue; }
    p.vy -= 12 * dt;
    p.m.position.x += p.vx * dt; p.m.position.y += p.vy * dt; p.m.position.z += p.vz * dt;
    p.m.rotation.x += dt * 5; p.m.rotation.y += dt * 7;
  }
}

/* ---------------- 物理 ---------------- */
function collides(px2, py2, pz2){
  const x0 = Math.floor(px2 - PR), x1 = Math.floor(px2 + PR);
  const y0 = Math.floor(py2), y1 = Math.floor(py2 + PH - 0.001);
  const z0 = Math.floor(pz2 - PR), z1 = Math.floor(pz2 + PR);
  for(let x = x0; x <= x1; x++) for(let y = y0; y <= y1; y++) for(let z = z0; z <= z1; z++)
    if(solidAt(x, y, z)) return true;
  return false;
}
function physStep(dt){
  // 输入方向
  let mx = 0, mz = 0;
  if(keys.KeyW) mz -= 1;
  if(keys.KeyS) mz += 1;
  if(keys.KeyA) mx -= 1;
  if(keys.KeyD) mx += 1;
  const cy = Math.cos(yawPitch.yaw), sy = Math.sin(yawPitch.yaw);
  let dx = (mx * cy - mz * sy), dz = (mx * -sy - mz * cy);
  const len = Math.hypot(dx, dz);
  if(len > 0){ dx /= len; dz /= len; }

  const headBlock = blockAt(Math.floor(pos.x), Math.floor(pos.y + 1.1), Math.floor(pos.z));
  const feetBlock = blockAt(Math.floor(pos.x), Math.floor(pos.y + 0.2), Math.floor(pos.z));
  inWater = feetBlock === 7 || headBlock === 7;
  const sprint = keys.ShiftLeft || keys.ShiftRight;
  const sneak = keys.ControlLeft || keys.ControlRight;

  let speed = sneak ? 1.8 : sprint ? 7.0 : 4.4;
  if(CREATIVE) speed *= 1.6;
  if(inWater) speed *= 0.6;

  const accel = onGround || inWater ? 42 : 14;
  vel.x += (dx * speed - vel.x) * Math.min(1, accel * dt);
  vel.z += (dz * speed - vel.z) * Math.min(1, accel * dt);

  if(inWater){
    vel.y += (keys.Space ? 5.2 : -3.2 - vel.y * 0.5) * dt * 3.5;
    vel.y = Math.max(-4, Math.min(4.5, vel.y));
  } else {
    vel.y -= GRAVITY * dt;
    if(keys.Space && onGround){ vel.y = JUMP_V; onGround = false; }
    if(CREATIVE){
      if(keys.Space) vel.y = 7.5;
      vel.y = Math.max(vel.y, -50);
    }
  }

  // 分轴移动
  const steps = Math.max(1, Math.ceil(dt / 0.008));
  const sdt = dt / steps;
  for(let s = 0; s < steps; s++){
    let nx = pos.x + vel.x * sdt;
    if(!collides(nx, pos.y, pos.z)) pos.x = nx; else vel.x = 0;
    let nz = pos.z + vel.z * sdt;
    if(!collides(pos.x, pos.y, nz)) pos.z = nz; else vel.z = 0;
    let ny = pos.y + vel.y * sdt;
    if(!collides(pos.x, ny, pos.z)){
      pos.y = ny; onGround = false;
    } else {
      if(vel.y < 0){
        onGround = true;
        // 贴地
        pos.y = Math.floor(pos.y) + (collides(pos.x, Math.floor(pos.y), pos.z) ? 1 : 0);
        if(vel.y < -12 && !inWater) sfx('step');
      }
      vel.y = 0;
    }
  }
  if(pos.y < -10){ pos.y = 90; vel.y = 0; toast('你掉出了世界！'); }

  // 脚步声与摆动
  const hv = Math.hypot(vel.x, vel.z);
  if(onGround && hv > 1.2){
    walkCycle += dt * hv * 1.6;
    stepTimer -= dt * hv;
    if(stepTimer <= 0){ stepTimer = 2.2; sfx('step', blockAt(Math.floor(pos.x), Math.floor(pos.y - 0.5), Math.floor(pos.z))); }
  }
  // 持续挖掘
  if(mouseDown[0]){
    if(breakTarget){
      const hit = raycast(5);
      if(hit && hit.x === breakTarget.x && hit.y === breakTarget.y && hit.z === breakTarget.z){
        breakProgress += dt;
        if(breakProgress >= breakTotal) finishBreak(breakTarget);
      } else startBreak();
    } else startBreak();
  } else breakTarget = null;

  // 选框
  const hit = raycast(5);
  if(hit){ selBox.visible = true; selBox.position.set(hit.x + 0.5, hit.y + 0.5, hit.z + 0.5); }
  else selBox.visible = false;
}

/* ---------------- 昼夜循环 ---------------- */
let timeOfDay = 0.3; // 0-1，0.25 = 正午? 这里 0=日出
function updateSky(dt){
  timeOfDay = (timeOfDay + dt / DAY_LEN) % 1;
  const ang = timeOfDay * Math.PI * 2;
  const sunH = Math.sin(ang); // >0 白天
  const dayF = Math.max(0, Math.min(1, (sunH + 0.12) / 0.24));
  const sx = Math.cos(ang) * 0.4, sy2 = Math.sin(ang), sz = 0.35;
  const dist = 400;
  const px2 = pos.x + sx * dist, py2 = pos.y + sy2 * dist, pz2 = pos.z + sz * dist;
  sunMesh.position.set(px2, py2, pz2);
  sunMesh.lookAt(camera.position);
  moonMesh.position.set(-px2, -py2, -pz2);
  moonMesh.lookAt(camera.position);
  skyMesh.position.set(pos.x, pos.y, pos.z);
  stars.position.set(pos.x, pos.y, pos.z);
  starMat.opacity = Math.max(0, 1 - dayF * 1.4);
  stars.visible = starMat.opacity > 0.02;

  const dayCol = new THREE.Color(0xc3ddff), nightCol = new THREE.Color(0x0b0e1a);
  const duskCol = new THREE.Color(0xe8935a);
  const skyT = new THREE.Color().copy(nightCol).lerp(dayCol, dayF);
  const duskAmt = Math.max(0, 1 - Math.abs(sunH) / 0.3) * (dayF > 0 ? 1 : 0.4);
  skyT.lerp(duskCol, duskAmt * 0.45);
  scene.fog.color.copy(skyT);
  skyMat.uniforms.top.value.copy(skyT).multiplyScalar(1.06);
  skyMat.uniforms.bot.value.copy(skyT);
  renderer.setClearColor(skyT);
  solidMat.uniforms.dayF.value = 0.14 + 0.86 * dayF;
  waterMat.uniforms.dayF.value = solidMat.uniforms.dayF.value;
  sunLight.position.set(sx, Math.max(0.08, sy2), sz);
  sunLight.intensity = 0.25 + dayF * 0.75;
  ambLight.intensity = 0.25 + dayF * 0.55;
}
