}

/* ---------------- 相机 ---------------- */
let thirdPerson = 0;
function updateCamera(dt){
  camera.rotation.set(0, 0, 0);
  camera.rotateY(yawPitch.yaw);
  camera.rotateX(yawPitch.pitch);
  const eye = pos.clone(); eye.y += EYE;
  if(thirdPerson > 0){
    const back = new THREE.Vector3(0, 0, 1).applyQuaternion(camera.quaternion);
    let d = thirdPerson === 1 ? 4 : 0;
    // 简单防穿墙
    const o = eye;
    while(d > 0.5 && solidAt(o.x + back.x * d, o.y + back.y * d, o.z + back.z * d)) d -= 0.25;
    camera.position.copy(eye).addScaledVector(back, d);
    if(thirdPerson === 2){ /* 正面视角暂用同距离 */ }
  } else {
    camera.position.copy(eye);
  }
  if(handMesh){
    if(swingT > 0){
      swingT -= dt;
      const k = Math.sin((0.28 - swingT) / 0.28 * Math.PI);
      handMesh.position.y -= k * 0.18;
      handMesh.rotation.x -= k * 0.9;
      handMesh.rotation.z += k * 0.4;
    }
  }
}

/* ---------------- UI ---------------- */
const $ = id => document.getElementById(id);
function updateHotbar(){
  const el = $('hotbar');
  el.innerHTML = '';
  hotbar.forEach((id, i) => {
    const s = document.createElement('div');
    s.className = 'slot' + (i === selSlot ? ' sel' : '');
    if(id){
      const img = document.createElement('img');
      const def = BLOCK_DEFS[id];
      const tile = def.tex.all !== undefined ? def.tex.all : (id === 1 ? 1 : def.tex.side ?? def.tex.cross ?? def.tex.top);
      img.src = iconCanvas(tile);
      s.appendChild(img);
      if(!CREATIVE && hotbarCounts[i] < 64){
        const n = document.createElement('span'); n.className = 'cnt'; n.textContent = hotbarCounts[i];
        s.appendChild(n);
      }
    }
    s.onclick = () => { selSlot = i; updateHotbar(); };
    el.appendChild(s);
  });
  const id = hotbar[selSlot];
  $('itemname').textContent = id ? (langEn ? BLOCK_NAMES_EN[id] : BLOCK_NAMES[id]) : '';
  $('itemname').style.opacity = id ? 1 : 0;
  clearTimeout(updateHotbar._t);
  updateHotbar._t = setTimeout(() => { $('itemname').style.opacity = 0; }, 1800);
  buildHandMesh(id);
