}
let langEn = false;
function renderInv(){
  const el = $('invgrid');
  el.innerHTML = '';
  invSlots.forEach((id, i) => {
    const s = document.createElement('div');
    s.className = 'slot';
    if(id){
      const img = document.createElement('img');
      const def = BLOCK_DEFS[id];
      const tile = def.tex.all !== undefined ? def.tex.all : (id === 1 ? 1 : def.tex.side ?? def.tex.cross ?? def.tex.top);
      img.src = iconCanvas(tile);
      s.appendChild(img);
      const n = document.createElement('span'); n.className = 'cnt'; n.textContent = invCounts[i];
      s.appendChild(n);
    }
    s.onclick = () => {
      // 与快捷栏交换
      const t = hotbar[selSlot], tc = hotbarCounts[selSlot];
      hotbar[selSlot] = id; hotbarCounts[selSlot] = invCounts[i];
      invSlots[i] = t; invCounts[i] = tc;
      updateHotbar(); renderInv();
    };
    el.appendChild(s);
  });
}
function toggleInv(force){
  invOpen = force !== undefined ? force : !invOpen;
  $('inv').style.display = invOpen ? 'flex' : 'none';
  if(invOpen){ renderInv(); document.exitPointerLock(); }
  else if(!document.pointerLockElement) cvs.requestPointerLock();
}
function toggleMode(){
  location.search = CREATIVE ? '?' : '?creative';
