    '生物群系: ' + biomeNameAt() + '<br>' +
    '时间: ' + clockStr() + (CREATIVE ? '<br>模式: 创造' : '');
}, 250);
function biomeNameAt(){
  // 简化：根据当前方块与高度推断
  const y = Math.floor(pos.y);
  if(y < SEA - 1) return langEn ? 'Ocean' : '海洋';
  return langEn ? 'Overworld' : '主世界';
}
function clockStr(){
  const total = ((timeOfDay + 0.25) % 1) * 24 * 60;
  const h = Math.floor(total / 60), m = Math.floor(total % 60);
  return h + ':' + (m < 10 ? '0' : '') + m;
}

/* ---------------- 存档 ---------------- */
let dirtySave = false;
function markDirtySave(){ dirtySave = true; }
const SAVE_KEY = 'mc_web_save_v1';
function saveLocal(){
  if(!dirtySave) return;
  dirtySave = false;
  try{
    const e = [];
    for(const [k, v] of edits){ const p = k.split(','); e.push([+p[0], +p[1], +p[2], v]); }
    localStorage.setItem(SAVE_KEY, JSON.stringify({
      seed, pos: [pos.x, pos.y, pos.z], yaw: yawPitch.yaw, pitch: yawPitch.pitch,
      time: timeOfDay, edits: e, hotbar, hotbarCounts, inv: invSlots, invC: invCounts
    }));
  }catch(err){}
}
function loadLocal(){
  try{
    const s = JSON.parse(localStorage.getItem(SAVE_KEY));
    if(!s) return false;
    seed = s.seed;
    for(const e of s.edits) edits.set(e[0] + ',' + e[1] + ',' + e[2], e[3]);
    if(s.pos){ pos.set(s.pos[0], s.pos[1], s.pos[2]); spawned = true; }
    if(s.yaw !== undefined) yawPitch.yaw = s.yaw;
    if(s.pitch !== undefined) yawPitch.pitch = s.pitch;
    if(s.time !== undefined) timeOfDay = s.time;
    if(s.hotbar){ hotbar.splice(0, 9, ...s.hotbar); hotbarCounts.splice(0, 9, ...s.hotbarCounts); }
    if(s.inv){ invSlots.splice(0, 27, ...s.inv); invCounts.splice(0, 27, ...s.invC); }
    return true;
  }catch(err){ return false; }
}
const SAVE_KEY2 = 'mc_web_seed_v1';
let hasSave = loadLocal();
if(!hasSave){
