let chunkTimer = 0;
function loop(){
  requestAnimationFrame(loop);
  const now = performance.now();
  let dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;
  if(workerReady){
    trySpawn();
    if(document.pointerLockElement) physStep(dt);
    else breakTarget = null;
    updateCamera(dt);
  }
  updateParticles(dt);
  updateSky(dt);
  chunkTimer -= dt;
  if(chunkTimer <= 0){ chunkTimer = 0.25; updateChunks(); saveLocal(); }
  renderer.render(scene, camera);
}
updateHotbar();
loop();
