html, body { width: 100%; height: 100%; overflow: hidden; background: #000; }
body { font-family: 'Segoe UI', 'Microsoft YaHei', sans-serif; user-select: none; }

#game { position: fixed; inset: 0; width: 100%; height: 100%; display: block; cursor: crosshair; }

/* 十字准星 */
#cross {
  position: fixed; left: 50%; top: 50%; width: 22px; height: 22px;
  transform: translate(-50%, -50%); pointer-events: none; display: none;
  mix-blend-mode: difference;
}
#cross::before, #cross::after {
  content: ''; position: absolute; background: #fff;
}
#cross::before { left: 50%; top: 0; width: 2px; height: 100%; transform: translateX(-50%); }
#cross::after { top: 50%; left: 0; height: 2px; width: 100%; transform: translateY(-50%); }

/* 调试信息（F3 风格） */
#debug {
  position: fixed; left: 8px; top: 8px; color: #fff; font-size: 12px;
  font-family: Consolas, monospace; text-shadow: 1px 1px 0 #000c;
  line-height: 1.5; pointer-events: none; z-index: 5;
}

