{"content":"// 无头冒烟测试：在 Node 里模拟 Worker 环境，跑一遍地形/光照/网格/编辑管线
const fs = require('fs');
const vm = require('vm');

const workerSrc = fs.readFileSync('worker.js', 'utf8');
const inbox = [];
const sandbox = {
  console, Math, Set, Map, Uint8Array, Float32Array, Uint32Array,
  performance: {now: () => Date.now()},
  postMessage: (msg) => inbox.push(msg),
  self: {}
};
vm.createContext(sandbox);
vm.runInContext(workerSrc, sandbox);
const send = m => sandbox.self.onmessage({data: m});

let pass = 0, fail = 0;
function check(name, cond){
  if(cond){ pass++; console.log('  ok  ' + name); }
  else { fail++; console.log('  FAIL ' + name); }
}

console.log('== init ==');
send({type: 'init', seed: 20240601});
check('initDone 应答', inbox.some(m => m.type === 'initDone'));

console.log('== 区块生成 ==');
const t0 = Date.now();
send({type: 'chunk', cx: 0, cz: 0, edits: []});
send({type: 'chunk', cx: 1, cz: 0, edits: []});
const genMs = Date.now() - t0;
console.log('  两个区块耗时 ' + genMs + ' ms');
const chunkMsgs = inbox.filter(m => m.type === 'chunk');
check('收到 2 个 chunk 应答', chunkMsgs.length === 2);
const c0 = chunkMsgs[0];
check('含方块数据 32KB', c0.blocks && c0.blocks.length === 16 * 16 * 128);
check('含实心网格', c0.solid && c0.solid.pos.length > 0 && c0.solid.idx.length > 0);
check('索引是 6 的倍数', c0.solid.idx.length % 6 === 0);
check('顶点数 = 索引去重(<=4/quad)', c0.solid.pos.length / 3 >= 4 && c0.solid.pos.length % 12 === 0);
check('uv/col/pos 数量一致', c0.solid.uv.length === c0.solid.pos.length / 3 * 2 && c0.solid.col.length === c0.solid.pos.length);

// 统计方块分布
const counts = {};
for(const b of c0.blocks) counts[b] = (counts[b] || 0) + 1;
console.log('  方块分布:', JSON.stringify(counts));
check('存在基岩(11)', counts[11] > 0);
check('存在石头(3)或泥土(2)', (counts[3] || 0) + (counts[2] || 0) > 0);
check('存在地表方块(草/沙/雪)', (counts[1] || 0) + (counts[4] || 0) + (counts[12] || 0) + (counts[21] || 0) > 0);

console.log('== 多种子多样性 ==');
const seeds = [1, 999, 123456789];
let totalDiff = new Set();
for(const s of seeds){
  inbox.length = 0;
  send({type: 'init', seed: s});
  send({type: 'chunk', cx: 0, cz: 0, edits: []});
  const m = inbox.find(x => x.type === 'chunk');
  for(const b of m.blocks) if(b) totalDiff.add(b);
}
console.log('  三种种子共出现方块种类: ' + totalDiff.size);
check('多种子方块种类 >= 8', totalDiff.size >= 8);

console.log('== 编辑与重网格化 ==');
inbox.length = 0;
// 在地表上放一个萤石（高亮度光源），再挖掉
send({type: 'chunk', cx: 0, cz: 0, edits: []});
const cm = inbox.find(x => x.type === 'chunk');
// 找最高实心点
let topY = 0;
for(let y = 127; y > 0; y--){ if(cm.blocks[(((0 << 4) | 0) << 7) | y]){ topY = y; break; } }
inbox.length = 0;
send({type: 'edit', x: 0, y: topY + 1, z: 0, id: 10}); // 萤石
const remesh1 = inbox.filter(m => m.type === 'remesh');
check('放置后触发重网格化', remesh1.length >= 1);
inbox.length = 0;
send({type: 'edit', x: 0, y: topY + 1, z: 0, id: 0}); // 挖掉
check('挖掉后触发重网格化', inbox.some(m => m.type === 'remesh'));

console.log('== 光照合理性（通过新区块网格） ==');
inbox.length = 0;
send({type: 'init', seed: 7});
send({type: 'chunk', cx: 0, cz: 0, edits: []});
const m7 = inbox.find(x => x.type === 'chunk');
// 网格里的光照通道：地表以上暴露面 sky 应接近 15/255
// 找到最高的实心方块，其上面那个方块的顶面应明亮——简化验证：所有 col.b 通道 <= 255
let maxB = 0;
for(let i = 2; i < m7.solid.col.length; i += 3) if(m7.solid.col[i] > maxB) maxB = m7.solid.col[i];
check('亮度乘子通道有效 (<=255)', maxB <= 255 && maxB > 100);

console.log('== 洞穴存在性（深度扫描） ==');
let caveAir = 0;
for(let lx = 0; lx < 16; lx++) for(let lz = 0; lz < 16; lz++) for(let y = 6; y < 25; y++)
  if(m7.blocks[(((lx << 4) | lz) << 7) | y] === 0) caveAir++;
console.log('  深层空气格数: ' + caveAir);
check('地下存在洞穴/空气', caveAir > 0);

console.log('== 性能 ==');
inbox.length = 0;
send({type: 'init', seed: 555});
const t1 = Date.now();
for(let cx = -3; cx <= 3; cx++) for(let cz = -3; cz <= 3; cz++) send({type: 'chunk', cx, cz, edits: []});
const t49 = Date.now() - t1;
console.log('  49 个区块生成+建网格耗时 ' + t49 + ' ms（均 ' + (t49 / 49).toFixed(1) + ' ms/块）');
check('单区块 < 400ms', t49 / 49 < 400);

console.log(fail === 0 ? '\n全部通过: ' + pass + ' 项' : '\n失败 ' + fail + ' 项 / 通过 ' + pass + ' 项');
process.exit(fail === 0 ? 0 : 1);
","path":"test.js"}

