function treeList(cx, cz){
  const out = [];
  for(let i = 0; i < 7; i++){
    const r1 = h2(cx * 3 + i * 7, cz * 7 - i * 13, 4000 + i);
    const r2 = h2(cx * 5 - i * 11, cz * 11 + i * 3, 5000 + i);
    const gx = cx * 16 + ((r1 * 16) | 0), gz = cz * 16 + ((r2 * 16) | 0);
    const h = heightAt(gx, gz);
    if(h <= SEA) continue;
    const bio = biomeAt(gx, gz, h);
    const maxA = bio === 1 ? 7 : bio === 0 ? 1 : bio === 3 ? 3 : 0;
    if(i >= maxA) continue;
    const r3 = h2(gx, gz, 6000 + i);
    const dens = bio === 1 ? 0.55 : bio === 0 ? 0.35 : 0.6;
    if(r3 > dens) continue;
    let ok = true;
    for(const t of out) if(Math.abs(t.gx - gx) < 3 && Math.abs(t.gz - gz) < 3){ ok = false; break; }
    if(!ok) continue;
    const spruce = bio === 3;
    const th = (spruce ? 5 : 4) + ((r3 * 997) | 0) % 3;
    out.push({gx, gz, ground: h, type: spruce ? 1 : 0, th});
  }
  if(treeCache.size > 20000) treeCache.clear();
  treeCache.set(ck, out);
  return out;
}
function stampTree(blocks, cx, cz, t){
  const x0 = cx * 16, z0 = cz * 16;
  const set = (wx, wy, wz, b, onlyAir) => {
    if(wx < x0 || wx >= x0 + 16 || wz < z0 || wz >= z0 + 16 || wy < 1 || wy >= HEIGHT) return;
    const i = (( (wx - x0) << 4 | (wz - z0) ) << 7) | wy;
    if(onlyAir && blocks[i] !== 0) return;
    blocks[i] = b;
  };
  const top = t.ground + t.th;
  if(t.type === 0){ // 橡树
    for(let dy = t.th - 2; dy <= t.th + 1; dy++){
      const r = dy <= t.th - 1 ? 2 : 1;
      for(let dx = -r; dx <= r; dx++) for(let dz = -r; dz <= r; dz++){
        if(Math.abs(dx) === r && Math.abs(dz) === r){
          if(dy > t.th - 1) continue;
          if(h3(t.gx + dx, t.ground + dy, t.gz + dz, 8800) < 0.5) continue;
        }
        set(t.gx + dx, t.ground + dy, t.gz + dz, 6, true);
      }
    }
    for(let y = t.ground + 1; y <= top; y++) set(t.gx, y, t.gz, 5, false);
