{"content":"'use strict';
/* ============================================================
   Minecraft 网页版 — Worker：地形生成 / 光照传播 / 网格构建
   优化：48×48 邻域 Region TypedArray，光照 BFS 与网格 AO 全走类型化数组
   ============================================================ */
const CHUNK = 16, HEIGHT = 128, SEA = 32;
let seed = 12345;

const cache = new Map();      // 数值键 -> Uint8Array 方块数据
const editMap = new Map();    // 数值键 -> Map(localIdx -> id) 永久保存玩家修改
let torchSet = new Set();     // 数值键 x,y,z 打包 -> 光源等级（0=无）

/* ---------------- 方块定义 ---------------- */
const BLOCKS = {
  1:{tex:{top:0,bottom:2,side:1}},
  2:{tex:{all:2}}, 3:{tex:{all:3}}, 4:{tex:{all:4}},
  5:{tex:{top:6,bottom:6,side:5}},
  6:{tex:{all:7}, transparent:true},
  7:{tex:{all:8}, transparent:true, liquid:true},
  8:{tex:{all:9}}, 9:{tex:{all:10}},
  10:{tex:{all:22}, light:15},
  11:{tex:{all:11}},
  12:{tex:{top:12,bottom:2,side:13}},
  13:{tex:{all:14}, transparent:true},
  14:{tex:{cross:15}, cross:true}, 15:{tex:{cross:16}, cross:true},
  16:{tex:{all:17}}, 17:{tex:{all:18}}, 18:{tex:{all:19}}, 19:{tex:{all:20}}, 20:{tex:{all:21}},
  21:{tex:{all:12}},
  31:{tex:{cross:23}, cross:true, light:14}
};
// OPAQUE 查找表：1=不透明实体（遮挡光线与渲染面）
const OPAQUE = new Uint8Array(64);
for(const k in BLOCKS){
  const d = BLOCKS[k];
  if(!d.transparent && !d.cross) OPAQUE[k] = 1;
}
function opaqueAt(b){ return OPAQUE[b] === 1; }

/* ---------------- 哈希与噪声 ---------------- */
function h2(x, z, s){
  let n = (x * 374761393 + z * 668265263 + (seed + s) * 974711) | 0;
  n = ((n ^ (n >>> 13)) * 1274126177) | 0;
  return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
}
function h3(x, y, z, s){
  let n = (x * 374761393 + y * 217645177 + z * 668265263 + (seed + s) * 974711) | 0;
  n = ((n ^ (n >>> 13)) * 1274126177) | 0;
  return ((n ^ (n >>> 16)) >>> 0) / 4294967296;
}
const sm = t => t * t * (3 - 2 * t);
function vnoise2(x, z, s){
  const xi = Math.floor(x), zi = Math.floor(z);
  const u = sm(x - xi), v = sm(z - zi);
  const a = h2(xi, zi, s), b = h2(xi + 1, zi, s), c = h2(xi, zi + 1, s), d = h2(xi + 1, zi + 1, s);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}
function fbm2(x, z, oct, s){
  let amp = 0.5, f = 1, sum = 0, norm = 0;
  for(let i = 0; i < oct; i++){ sum += vnoise2(x * f, z * f, s + i * 77) * amp; norm += amp; amp *= 0.5; f *= 2; }
  return sum / norm;
}
function vnoise3(x, y, z, s){
  const xi = Math.floor(x), yi = Math.floor(y), zi = Math.floor(z);
  const u = sm(x - xi), v = sm(y - yi), w = sm(z - zi);
  const n000=h3(xi,yi,zi,s),   n100=h3(xi+1,yi,zi,s),   n010=h3(xi,yi+1,zi,s),   n110=h3(xi+1,yi+1,zi,s);
  const n001=h3(xi,yi,zi+1,s), n101=h3(xi+1,yi,zi+1,s), n011=h3(xi,yi+1,zi+1,s), n111=h3(xi+1,yi+1,zi+1,s);
  const x00=n000+(n100-n000)*u, x10=n010+(n110-n010)*u, x01=n001+(n101-n001)*u, x11=n011+(n111-n011)*u;
  const y0=x00+(x10-x00)*v, y1=x01+(x11-x01)*v;
  return y0 + (y1 - y0) * w;
}

/* ---------------- 树木（确定性，跨区块一致） ---------------- */
const treeCache = new Map();
function treeList(cx, cz){
  const ck = (cx + 32768) * 65536 + (cz + 32768);
  let out = treeCache.get(ck);
  if(out) return out;
  out = [];
  for(let i = 0; i < 7; i++){
    const r1 = h2(cx * 3 + i * 7, cz * 7 - i * 13, 4000 + i);
    const r2 = h2(cx * 5 - i * 11, cz * 11 + i * 3, 5000 + i);
    const gx = cx * 16 + ((r1 * 16) | 0), gz = cz * 16 + ((r2 * 16) | 0);
    const h = heightAt(gx, gz);
    if(h <= SEA) continue;
    const bio = biomeAt(gx, gz, h);
    const maxA = bio === 1 ? 7 : bio === 0 ? 1 : bio === 3 ? 3 : 0;
    if(i >= maxA) continue;
    const r3 = h2(gx, gz, 6000 + i);
    const dens = bio === 1 ? 0.55 : bio === 0 ? 0.35 : 0.6;
    if(r3 > dens) continue;
    let ok = true;
    for(const t of out) if(Math.abs(t.gx - gx) < 3 && Math.abs(t.gz - gz) < 3){ ok = false; break; }
    if(!ok) continue;
    const spruce = bio === 3;
    const th = (spruce ? 5 : 4) + ((r3 * 997) | 0) % 3;
    out.push({gx, gz, ground: h, type: spruce ? 1 : 0, th});
  }
  if(treeCache.size > 20000) treeCache.clear();
  treeCache.set(ck, out);
