  if(t.type === 0){ // 橡树
    for(let dy = t.th - 2; dy <= t.th + 1; dy++){
      const r = dy <= t.th - 1 ? 2 : 1;
      for(let dx = -r; dx <= r; dx++) for(let dz = -r; dz <= r; dz++){
        if(Math.abs(dx) === r && Math.abs(dz) === r){
          if(dy > t.th - 1) continue;
          if(h3(t.gx + dx, t.ground + dy, t.gz + dz, 8800) < 0.5) continue;
        }
        set(t.gx + dx, t.ground + dy, t.gz + dz, 6, true);
