    }
    for(let y = t.ground + 1; y <= top; y++) set(t.gx, y, t.gz, 5, false);
  } else { // 云杉
    for(let dy = 2; dy <= t.th; dy++){
      let r = ((t.th - dy) % 2 === 0) ? 1 : 2;
      if(dy >= t.th) r = 1;
      for(let dx = -r; dx <= r; dx++) for(let dz = -r; dz <= r; dz++){
        if(r === 2 && Math.abs(dx) === 2 && Math.abs(dz) === 2) continue;
        set(t.gx + dx, t.ground + dy, t.gz + dz, 6, true);
      }
    }
    set(t.gx, top + 1, t.gz, 6, true);
    for(let y = t.ground + 1; y <= top; y++) set(t.gx, y, t.gz, 5, false);
