/* ---------------- 区块生成 ---------------- */
const key = (cx, cz) => (cx + 32768) * 65536 + (cz + 32768);
const idx = (lx, lz, y) => (((lx << 4) | lz) << 7) | y;

const hCache = new Map(), bCache = new Map();
function heightAt(gx, gz){
  const k = (gx + 524288) * 1048576 + (gz + 524288);
  let v = hCache.get(k);
  if(v !== undefined) return v;
  const base = fbm2(gx * 0.0065, gz * 0.0065, 4, 0);
  const m = fbm2(gx * 0.0045 + 911, gz * 0.0045 - 73, 3, 1000);
  let r = Math.max(0, m - 0.56) / 0.44; r = r * r;
  v = Math.max(4, Math.min(122, Math.round(22 + (base - 0.5) * 30 + r * 62)));
  if(hCache.size > 400000) hCache.clear();
  hCache.set(k, v);
  return v;
}
// 0平原 1森林 2沙漠 3雪山 4海洋
function biomeAt(gx, gz, h){
  const k = (gx + 524288) * 1048576 + (gz + 524288);
  let v = bCache.get(k);
  if(v !== undefined) return v;
  const t = fbm2(gx * 0.0035 + 991, gz * 0.0035 + 137, 3, 2000);
  const m = fbm2(gx * 0.0035 - 517, gz * 0.0035 + 89, 3, 3000);
  if(h <= SEA - 2) v = 4;
  else if(h > 76 || t < 0.34) v = 3;
  else if(t > 0.62 && m < 0.45) v = 2;
  else if(m > 0.54) v = 1;
  else v = 0;
  if(bCache.size > 400000) bCache.clear();
  bCache.set(k, v);
