}

function genColumn(cx, cz){
  const blocks = new Uint8Array(16 * 16 * HEIGHT);
  for(let lx = 0; lx < 16; lx++) for(let lz = 0; lz < 16; lz++){
    const gx = cx * 16 + lx, gz = cz * 16 + lz;
    const h = heightAt(gx, gz);
    const bio = biomeAt(gx, gz, h);
    const sandy = (h <= SEA + 1 && bio !== 3) || bio === 2;
    for(let y = 0; y <= h; y++){
      let b;
