        if(y < 96 && h3(cxx, cyy, czz, 6100) < 0.035) b = 17;
        else if(y < 56 && h3(cxx, cyy, czz, 6200) < 0.022) b = 18;
        else if(y < 32 && h3(cxx, cyy, czz, 6300) < 0.012) b = 19;
