/* ---------------- Region：48×48 邻域数据（含 1 圈缓冲） ---------------- */
const RL = 48, RM = 16;              // 区域边长 / 缓冲宽
const reg = new Uint8Array(RL * RL * HEIGHT);   // 方块
const regSky = new Uint8Array(RL * RL * HEIGHT);// 天光
const regBlk = new Uint8Array(RL * RL * HEIGHT);// 方块光
