  for(let lx = 0; lx < 16; lx++) for(let lz = 0; lz < 16; lz++){
    const rcol = rIdx(LX0 + lx, LZ0 + lz, 0);
    const top = regTop[(LX0 + lx) * RL + (LZ0 + lz)];
    for(let y = 0; y <= top; y++){
      const b = reg[rcol | y];
      if(b === 0) continue;
      const def = BLOCKS[b];
      const rx = LX0 + lx, rz = LZ0 + lz;

      if(def.cross){ // 十字植物（双面）
        const [u0, v0, u1, v1] = TUV(def.tex.cross);
        const li = rcol | y;
        const s = regSky[li] / 15, bl = regBlk[li] / 15;
        const q1 = [[lx+0.12,y,lz+0.12],[lx+0.88,y,lz+0.88],[lx+0.12,y+1,lz+0.12],[lx+0.88,y+1,lz+0.88]];
        const q2 = [[lx+0.88,y,lz+0.65],[lx+0.12,y,lz+0.35],[lx+0.88,y+1,lz+0.65],[lx+0.12,y+1,lz+0.35]];
        for(const q of [q1, q2]) for(const flip of [0, 1]){
          const base = S.pos.length / 3;
          const verts = [
            [q[0][0],q[0][1],q[0][2], u0, v0],
            [q[1][0],q[1][1],q[1][2], u1, v0],
            [q[2][0],q[2][1],q[2][2], u0, v1],
            [q[3][0],q[3][1],q[3][2], u1, v1]
          ];
          if(flip) verts.reverse();
          for(const v of verts){
            S.pos.push(v[0], v[1], v[2]);
            S.uv.push(v[3], v[4]);
            S.col.push((s * 255) | 0, (bl * 255) | 0, 255);
          }
          S.idx.push(base, base + 1, base + 2, base + 2, base + 1, base + 3);
        }
        continue;
      }

      const isWater = b === 7;
      const aboveB = y + 1 < HEIGHT ? reg[rcol | (y + 1)] : 0;
      const topOffset = (isWater && aboveB !== 7) ? 0.125 : 0;
      const A = isWater ? W : S;

      for(let fi = 0; fi < 6; fi++){
        const f = FACES[fi];
        const nrx = rx + f.d[0], ny = y + f.d[1], nrz = rz + f.d[2];
        const n = ny < 0 ? 11 : ny >= HEIGHT ? 0 : reg[rIdx(nrx, nrz, ny)];
        if(isWater){ if(n === 7 || OPAQUE[n]) continue; if(fi === 3 && aboveB === 7) continue; }
        else if(b === 13){ if(n === 13 || OPAQUE[n]) continue; }
        else if(OPAQUE[n]) continue;

        const tex = def.tex;
        const tile = tex.all !== undefined ? tex.all : (fi === 3 ? tex.top : fi === 2 ? tex.bottom : tex.side);
        const col = tile % 8, row = (tile / 8) | 0, pad = 0.02;
        const u0 = (col + pad) / 8, u1 = (col + 1 - pad) / 8;
        const v0 = 1 - (row + 1 - pad) / 3, v1 = 1 - (row + pad) / 3;

        const li = rIdx(nrx, nrz, ny);
        const s = regSky[li] / 15, bl = regBlk[li] / 15;

        const base = A.pos.length / 3;
        for(let vi = 0; vi < 4; vi++){
          const c = f.c[vi];
          let vy = y + c[1];
          if(topOffset && c[1] === 1) vy = y + 1 - topOffset;
          // 逐顶点 AO
          let m = f.m;
          let s1, s2, o1x, o1y, o1z, o2x, o2y, o2z;
          if(f.d[0] !== 0){
            s1 = c[1] ? 1 : -1; s2 = c[2] ? 1 : -1;
            o1x = 0; o1y = s1; o1z = 0; o2x = 0; o2y = 0; o2z = s2;
          } else if(f.d[1] !== 0){
            s1 = c[0] ? 1 : -1; s2 = c[2] ? 1 : -1;
            o1x = s1; o1y = 0; o1z = 0; o2x = 0; o2y = 0; o2z = s2;
          } else {
            s1 = c[0] ? 1 : -1; s2 = c[1] ? 1 : -1;
            o1x = s1; o1y = 0; o1z = 0; o2x = 0; o2y = s2; o2z = 0;
          }
          const a1 = OPAQUE[reg[rIdx(nrx + o1x, Math.min(HEIGHT - 1, Math.max(0, ny + o1y)), nrz + o1z)]];
          const a2 = OPAQUE[reg[rIdx(nrx + o2x, Math.min(HEIGHT - 1, Math.max(0, ny + o2y)), nrz + o2z)]];
          const ac = OPAQUE[reg[rIdx(nrx + o1x + o2x, Math.min(HEIGHT - 1, Math.max(0, ny + o1y + o2y)), nrz + o1z + o2z)]];
          const ao = (a1 && a2) ? 0 : 3 - (a1 + a2 + ac);
          m = f.m * aoMult[ao];
          A.pos.push(lx + c[0], vy, lz + c[2]);
          A.uv.push(u0 + (u1 - u0) * c[3], v0 + (v1 - v0) * c[4]);
          A.col.push((s * 255) | 0, (bl * 255) | 0, Math.min(255, (m * 255)) | 0);
        }
        A.idx.push(base, base + 1, base + 2, base + 2, base + 1, base + 3);
      }
