  const pack = A => A.pos.length === 0 ? null : {
    pos: new Float32Array(A.pos), uv: new Float32Array(A.uv),
    col: new Uint8Array(A.col), idx: new Uint32Array(A.idx)
  };
  return {solid: pack(S), water: pack(W)};
}

/* ---------------- 消息处理 ---------------- */
function mergeEdits(edits){
  if(!edits) return;
  for(const e of edits){
    const x = e[0], y = e[1], z = e[2], id = e[3];
    const k = key(x >> 4, z >> 4);
    let em = editMap.get(k);
    if(!em){ em = new Map(); editMap.set(k, em); }
    em.set(idx(x & 15, z & 15, y), id);
    const pk = x + ',' + y + ',' + z;
    const lvl = id === 10 ? 15 : id === 31 ? 14 : 0;
    if(lvl) { torchMap.set(pk, [x, y, z, lvl]); torchSet.add(pk); }
    else { torchMap.delete(pk); torchSet.delete(pk); }
    const c = cache.get(k);
    if(c) c[idx(x & 15, z & 15, y)] = id;
  }
}
function postGeometry(type, cx, cz, withBlocks){
  const res = buildMesh(cx, cz);
  const msg = {type, cx, cz, solid: res.solid, water: res.water};
  const tr = [];
  if(withBlocks){
    msg.blocks = ensureCol(cx, cz).slice(0);
    tr.push(msg.blocks.buffer);
  }
  for(const g of [res.solid, res.water]) if(g){
    tr.push(g.pos.buffer, g.uv.buffer, g.col.buffer, g.idx.buffer);
  }
  postMessage(msg, tr);
}
function handleEdit(x, y, z, id){
  mergeEdits([[x, y, z, id]]);
  const cx = x >> 4, cz = z >> 4;
  const cands = new Set();
  const x0 = (x - 14) >> 4, x1 = (x + 14) >> 4, z0 = (z - 14) >> 4, z1 = (z + 14) >> 4;
  for(let ncx = x0; ncx <= x1; ncx++) for(let ncz = z0; ncz <= z1; ncz++) cands.add(ncx + ',' + ncz);
  for(const ks of cands){
    const [ccx, ccz] = ks.split(',').map(Number);
    // 重建区域（编辑可能影响邻块列数据）→ computeLight 内部检测 Rcx/Rcz 变化才重建
    computeLight(ccx, ccz);
    const ns = extractCol(ccx, ccz, regSky), nb = extractCol(ccx, ccz, regBlk);
    const prev = lightCache.get(ks);
    let changed = !prev || prev.sky.length !== ns.length;
    if(!changed){
      for(let i = 0; i < ns.length; i++) if(prev.sky[i] !== ns[i] || prev.blk[i] !== nb[i]){ changed = true; break; }
    }
    const borderN = (ccx === cx && ccz === cz + 1 && (z & 15) >= 14) ||
                    (ccx === cx && ccz === cz - 1 && (z & 15) <= 1) ||
                    (ccz === cz && ccx === cx + 1 && (x & 15) >= 14) ||
                    (ccz === cz && ccx === cx - 1 && (x & 15) <= 1);
    if(changed || borderN || (ccx === cx && ccz === cz)){
      lightCache.set(ks, {sky: ns, blk: nb});
      postGeometry('remesh', ccx, ccz, false);
    }
  }
}
const lightCache = new Map();

self.onmessage = e => {
  const m = e.data;
  if(m.type === 'init'){
    seed = m.seed | 0;
    cache.clear(); editMap.clear(); lightCache.clear();
    torchSet = new Set(); torchMap.clear();
    hCache.clear(); bCache.clear(); treeCache.clear();
    Rcx = 1e9; Rcz = 1e9;
    postMessage({type: 'initDone'});
  }
  else if(m.type === 'chunk'){
    mergeEdits(m.edits);
    ensureCol(m.cx, m.cz);
    postGeometry('chunk', m.cx, m.cz, true);
  }
  else if(m.type === 'edit'){
    handleEdit(m.x, m.y, m.z, m.id);
  }
};
