{"content":"// 编辑管线行为测试（挖穿 / 光源）
const vm = require('vm'), fs = require('fs');
const src = fs.readFileSync('worker.js', 'utf8');
let msgs = [];
const sb = {
  console, Math, Set, Map, Uint8Array, Float32Array, Uint32Array,
  performance: {now: () => Date.now()},
  postMessage: m => msgs.push(m),
  self: {}
};
vm.createContext(sb);
vm.runInContext(src, sb);
const send = m => sb.self.onmessage({data: m});

send({type: 'init', seed: 2024});
for(const [cx, cz] of [[0,0],[1,0],[0,1],[1,1]]) send({type: 'chunk', cx, cz, edits: []});

let top = 0;
const before = sb.ensureCol(0, 0);
for(let y = 127; y > 0; y--){ if(before[(((0 << 4) | 0) << 7) | y]){ top = y; break; } }
console.log('地表高度:', top);

// 挖穿 3 格：每次都应触发中心块重网格
msgs = [];
for(let d = 0; d < 3; d++) send({type: 'edit', x: 0, y: top - d, z: 0, id: 0});
const rm = msgs.filter(m => m.type === 'remesh' && m.cx === 0 && m.cz === 0).length;
console.log('挖穿3格中心块重网格次数:', rm);
if(rm < 3){ console.error('FAIL'); process.exit(1); }

// 挖穿后光应能照进洞底：提取光照验证
msgs = [];
send({type: 'edit', x: 0, y: top + 1, z: 0, id: 31}); // 放火把在洞口旁
console.log('放火把触发重网格:', msgs.filter(m => m.type === 'remesh').length, '次');
if(msgs.length === 0){ console.error('FAIL: 放火把无响应'); process.exit(1); }

// 火把周围方块光应 > 0
sb.computeLight(0, 0);
const li = sb.rIdx(sb.RM + 0, sb.RM + 0, top);
console.log('洞口天光:', sb.regSky[li], '方块光:', sb.regBlk[li]);
if(sb.regBlk[li] < 5){ console.error('FAIL: 火把光未传播'); process.exit(1); }

// 收回火把，光应熄灭
msgs = [];
send({type: 'edit', x: 0, y: top + 1, z: 0, id: 0});
sb.computeLight(0, 0);
console.log('收回火把后方块光:', sb.regBlk[li]);
if(sb.regBlk[li] !== 0){ console.error('FAIL: 火把光未熄灭'); process.exit(1); }

console.log('编辑管线测试全部通过');
