{"content":"// 编辑延迟测试：测量单次 edit 的处理耗时（应 < 100ms 才无卡顿感）
const vm = require('vm'), fs = require('fs');
const src = fs.readFileSync('worker.js', 'utf8');
let msgs = [];
const sb = {
  console, Math, Set, Map, Uint8Array, Float32Array, Uint32Array,
  performance: {now: () => Date.now()},
  postMessage: m => msgs.push(m),
  self: {}
};
vm.createContext(sb);
vm.runInContext(src, sb);
const send = m => sb.self.onmessage({data: m});

send({type: 'init', seed: 2024});
for(let cx = -1; cx <= 2; cx++) for(let cz = -1; cz <= 2; cz++) send({type: 'chunk', cx, cz, edits: []});

let top = 0;
const col = sb.ensureCol(0, 0);
for(let y = 127; y > 0; y--){ if(col[(((0 << 4) | 0) << 7) | y]){ top = y; break; } }

// 预热
send({type: 'edit', x: 8, y: top, z: 8, id: 0});
send({type: 'edit', x: 8, y: top, z: 8, id: 3});

let worst = 0, sum = 0, n = 20;
for(let i = 0; i < n; i++){
  const t0 = Date.now();
  send({type: 'edit', x: 8 + (i % 3), y: top + 1 + (i % 2), z: 8, id: i % 2 ? 0 : 8});
  const dt = Date.now() - t0;
  worst = Math.max(worst, dt); sum += dt;
}
console.log('编辑耗时: 平均', (sum / n).toFixed(1), 'ms, 最差', worst, 'ms');
if(worst > 120){ console.error('FAIL: 编辑延迟过高'); process.exit(1); }
console.log('编辑延迟测试通过');
